style.css:
@-moz-document domain("roblox.com") {
/* Genel font ve background */
    body {
        background: url("https://i.imgur.com/e5QeL7F.jpg") repeat !important;
        font-family: Tahoma, Arial, sans-serif !important;
        color: black !important;
    }

    /* Header */
    header, .navbar, .navigation-bar {
        background-color: #1A3C6B !important;
        color: white !important;
    }

    /* Eski logo */
    .navbar-logo img {
        content: url("https://upload.wikimedia.org/wikipedia/en/5/5a/Roblox_2005_logo.png") !important;
        height: auto !important;
        max-height: 40px !important;
    }

    /* Butonlar */
    button, .btn-primary, .btn-secondary {
        background-color: #C0C0C0 !important;
        border: 2px outset #808080 !important;
        color: black !important;
        font-weight: bold !important;
        border-radius: 2px !important;
    }

    /* Mobil uyum (responsive) */
    * {
        box-sizing: border-box;
    }

    img, video {
        max-width: 100% !important;
        height: auto !important;
    }

    .container, .main-content {
        padding: 10px !important;
        width: 100% !important;
        max-width: 1200px !important;
        margin: auto !important;
    }

    /* Linkler */
    a {
        color: #0033cc !important;
    }

    /* Footer */
    footer {
        background-color: #1A3C6B !important;
        color: white !important;
    }
}
